#include "../security/onion/resource.h"
#include "../kernel/policy.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static struct ramfs ram;
static int rd(void*c,uint64_t lba,unsigned count,void*o){FILE*f=c;return !fseek(f,(long)(lba*512),SEEK_SET)&&fread(o,512,count,f)==count;}
static void zero(const void *p,size_t n){const unsigned char*b=p;while(n--)assert(!*b++);}
int main(void){struct resource_request r;struct resource_snapshot s;struct app_session a;char out[256];ramfs_init(&ram);assert(!ramfs_mkdir(&ram,"docs"));assert(!ramfs_write(&ram,"docs/granted","hello-swamp",11));assert(!ramfs_write(&ram,"private","secret",6));assert(resource_parse("/bin/integration-demo ram:docs/granted",&r));assert(resource_prepare(&r,&ram,0,&s)&&s.length==11&&!memcmp(s.bytes,"hello-swamp",11));assert(!ramfs_write(&ram,"docs/granted","changed",7));assert(session_begin(&a,1,CAP_DATA,s.bytes,s.length));resource_clear(&s);zero(&s,sizeof s);assert(session_read(&a,0,out,sizeof out)==11&&!memcmp(out,"hello-swamp",11));assert(session_read(&a,11,out,1)==0);assert(session_read(&a,UINT64_MAX,out,1)==0);session_clear(&a);zero(&a,sizeof a);assert(session_read(&a,0,out,1)==-1);
 const char *bad[]={"/bin/hello ram:../private","/bin/hello ram:/private","/bin/hello ext:welcome.txt","/bin/hello ext:/../welcome.txt","/bin/hello ext:/bin//hello","/bin/hello ext:/bin/","/bin/hello ram:docs/granted extra","/bin/../hello ram:private","relative ram:private","/bin/hello unknown:private","/bin/hello ram:","/bin/hello ram:docs\\granted","/bin/hello ram:docs/./granted"};for(size_t i=0;i<sizeof bad/sizeof *bad;i++){assert(!resource_parse(bad[i],&r));zero(&r,sizeof r);}
 unsigned char big[RAMFS_BYTES]={0};assert(!ramfs_write(&ram,"big",big,sizeof big));assert(resource_parse("/bin/hello ram:big",&r));memset(&s,0xa5,sizeof s);assert(resource_prepare(&r,&ram,0,&s)&&s.length==sizeof big);resource_clear(&s);zero(&s,sizeof s);
 FILE*f=fopen("build/vault.ext4","rb");assert(f&&!fseek(f,0,SEEK_END));struct blockdev dev={f,(uint64_t)ftell(f)/512,rd};struct ext4 ext;assert(ext4_mount(&ext,&dev));assert(resource_parse("/bin/hello ext:/welcome.txt",&r)&&resource_prepare(&r,&ram,&ext,&s)&&s.length>13&&!memcmp(s.bytes,"SwampOS Vault",13));assert(resource_parse("/bin/hello ext:/pattern.bin",&r)&&resource_prepare(&r,&ram,&ext,&s)&&s.length==9000);for(unsigned i=0;i<9000;i++)assert(s.bytes[i]==(unsigned char)(i*31u+7u));resource_clear(&s);const char*rejected[]={"/bin/hello ext:/bin","/bin/hello ext:/missing","/bin/hello ram:docs"};for(size_t i=0;i<sizeof rejected/sizeof *rejected;i++){assert(resource_parse(rejected[i],&r));memset(&s,0xa5,sizeof s);assert(!resource_prepare(&r,&ram,&ext,&s));zero(&s,sizeof s);}fclose(f);
 for(unsigned i=0;i<50000;i++){unsigned n=i%257;memset(out,(int)(i&255),n);assert(!ramfs_write(&ram,"docs/granted",out,n));assert(resource_parse(" /bin/hello  ram:docs/granted  ",&r));assert(resource_prepare(&r,&ram,0,&s)&&s.length==n&&!memcmp(s.bytes,out,n));assert(session_begin(&a,1,CAP_DATA,s.bytes,n));resource_clear(&s);zero(&s,sizeof s);assert(session_read(&a,0,out,256)==(long)n);session_clear(&a);zero(&a,sizeof a);}
 puts("RESOURCE_HOST_OK: 50000 snapshots, explicit paths, real EXT4, size/type rejection, immutable per-run data and scrubbing");return 0;}
